INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (13, 1, 'theory', 'Quiz: the first program');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (13, 1, 0, 'What does the print command do?', '["Prints text on paper", "Shows the value it is given on the screen", "Saves a value to a file", "Starts a program"]', 1, 'print prints to the screen. There is no paper: the name is left over from the era of printers.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (13, 1, 1, 'Which quotes can be used for a string in Python?', '["Only single quotes", "Only double quotes", "Single or double, as long as they are the same on both sides", "No quotes at all"]', 2, 'Single and double quotes are equal; what matters is that the fence matches on both sides.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (13, 1, 2, 'A program has three print commands in a row. In what order will they run?', '["Top to bottom, one line at a time", "Bottom to top", "In random order", "All at the same time"]', 0, 'A program is a recipe: the machine reads the commands one by one, from top to bottom.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (13, 1, 3, 'What will Python do with the rest of a line after the # symbol?', '["Run it first", "Ignore it completely", "Show it on the screen", "Report an error"]', 1, 'Everything after the hash sign on a line is a comment: a note for people, not for the machine.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (13, 1, 4, 'print(''2 + 2'') and print(2 + 2): what will they print?', '["Both will print 4", "Both will print 2 + 2", "The first prints 2 + 2, the second prints 4", "The first prints 4, the second prints 2 + 2"]', 2, 'In quotes it is just text; without them it is arithmetic, which Python will calculate.');
